{
    "title": "popupElement text",
    "type": "object",
    "$schema": "http://json-schema.org/draft-04/schema",
    "description": "Configures text in popup elements.",
    "properties": {
        "text": {
            "type": "string",
            "description": "This property applies to elements of type `text`. This is string value indicating the text to be displayed within the popupElement. If no `text` property is provided, the popupElement will display whatever is specified in the [popupInfo.description](popupInfo.md) property."
        },
        "type": {
            "type": "string",
            "enum": [
                "text"
            ]
        }
    },
    "required": [
        "type"
    ],
    "additionalProperties": false,
    "esriDocumentation": {
        "examples": [
            {
                "title": "popupElement",
                "code": {
                    "popupElements": [
                        {
                            "type": "text",
                            "text": "Some descriptive text describing the popup."
                        }
                    ]
                }
            }
        ]
    }
}

{
    "title": "search layer field",
    "type": "object",
    "$schema": "http://json-schema.org/draft-04/schema",
    "description": "Contains information about an attribute field in search layer configuration.",
    "properties": {
        "exactMatch": {
            "type": "boolean",
            "description": "A Boolean defining whether or not the field is an exact match."
        },
        "name": {
            "type": "string",
            "description": "A string defining the field name."
        },
        "type": {
            "type": "string",
            "description": "A string defining the field type.",
            "enum": [
                "esriFieldTypeBlob",
                "esriFieldTypeDate",
                "esriFieldTypeDouble",
                "esriFieldTypeGUID",
                "esriFieldTypeGeometry",
                "esriFieldTypeGlobalID",
                "esriFieldTypeInteger",
                "esriFieldTypeLong",
                "esriFieldTypeOID",
                "esriFieldTypeRaster",
                "esriFieldTypeSingle",
                "esriFieldTypeSmallInteger",
                "esriFieldTypeString",
                "esriFieldTypeXML"
            ]
        }
    },
    "additionalProperties": false,
    "esriDocumentation": {
        "examples": [
            {
                "title": "search layer field",
                "code": {
                    "field": {
                        "name": "relationships/2/Postcode",
                        "type": "esriFieldTypeString",
                        "exactMatch": true
                    }
                }
            }
        ]
    }
}

{
    "$schema": "http://json-schema.org/draft-04/schema#",
    "title": "RecipientProfile schema",
    "description": "A Blockcerts extension allowing inclusion of additional recipient details, including recipient publicKey and name. Inclusion of the recipient publicKey allows the recipient to make a strong claim of ownership over the key, and hence the badge being awarded. In the future, publicKey will be deprecated in favor of a decentralized id (DID) in the `id` field.",
    "type": "object",
    "properties": {
        "id": {
            "type": "string",
            "description": "reserved for future use as DID"
        },
        "name": {
            "type": "string",
            "description": "Name of recipient, http://schema.org/name"
        },
        "publicKey": {
            "type": "string",
            "format": "uri",
            "description": "In Blockcerts `publicKey` IRIs are typically represented with a `<scheme>:` prefix. For Bitcoin transactions, this would be the recipient public Bitcoin address prefixed with `ecdsa-koblitz-pubkey:`; e.g. `ecdsa-koblitz-pubkey:14RZvYazz9H2DC2skBfpPVxax54g4yabxe`"
        }
    }
}

