        "string"
    ],
    "oneOf": [
        {
            "type": "integer"
        },
        {
            "$ref": "#/definitions/fraction"
        },
        {
            "$ref": "#/definitions/ieee754"
        }
    ],
    "definitions": {
        "fraction": {
            "description": "A stringified fraction. For example ``4/7'' or ``-11/3''.",
            "type": "string",
            "pattern": "^-?\\d+/\\d+$"
