        "ieee754": {
            "description": "A stringified IEEE-754 value in ``%a'' format. For example, ``sqrt(2)`` is nearest to ``0x1.6a09e667f3bcdp+0''.",
            "type": "string",
            "pattern": "^-?0x1\\.[0-9a-f]{13}p[+-]\\d+$"
        }
    }
}

